package de.hhu.stups.xml2b;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.Test;

import java.io.File;

/**
 * @author generated by Claude
 */
public class OptionsTest {

	@Test
	void testOutputFileWithoutDirectory() {
		XML2BOptions options = XML2BOptions.defaultOptions(new File("data.xml")).withOutputFile(new File("out.mch"));
		Assertions.assertEquals("out", options.machineName());
		Assertions.assertEquals(new File("").getAbsoluteFile().toPath(), options.directory());
	}

	@Test
	void testFileNameWithoutExtension() {
		XML2BOptions options = XML2BOptions.defaultOptions(new File("README"));
		Assertions.assertEquals("README", options.machineName());
	}

	@Test
	void testPrologSystemIsCaseInsensitive() {
		XML2BOptions defaults = XML2BOptions.defaultOptions(new File("data.xml"));
		Assertions.assertEquals(XML2BOptions.SWI_NAME, defaults.withPrologSystem("SWI").frwPrologSystem());
		Assertions.assertEquals(XML2BOptions.SICSTUS_NAME, defaults.withPrologSystem("SICSTUS").frwPrologSystem());
		Assertions.assertNull(defaults.withPrologSystem("NONE").frwPrologSystem());
		Assertions.assertThrows(IllegalArgumentException.class, () -> defaults.withPrologSystem("yap"));
	}
}
